#include <iostream>

void aumenta(int& valore, int delta) {
    // Il riferimento e un alias dell'intero del chiamante.
    valore += delta;
}

int main() {
    int valore{}, delta{};
    if (!(std::cin >> valore >> delta)) return 0;
    aumenta(valore, delta);
    std::cout << valore << '\n';
}

