#include <iostream>
#include <cstddef>

int leggi(const int* dati, std::size_t colonne,
          std::size_t r, std::size_t c) {
    // Salta r righe complete, poi avanza di c elementi.
    return dati[r * colonne + c];
}

int main() {
    std::size_t righe{}, colonne{}, r{}, c{};
    int dati[12]{};
    if (!(std::cin >> righe >> colonne)) return 0;
    // L'input rispetta i vincoli dichiarati nella consegna.
    for (std::size_t i = 0; i < righe * colonne; ++i) {
        std::cin >> dati[i];
    }
    std::cin >> r >> c;
    std::cout << leggi(dati, colonne, r, c) << '\n';
}

